//! `contracts`: the committed contract documents, generated from code, with a drift check.
//!
//! Three documents are contracts with clients and consumers (`ENGINEERING_RULES` R7, PLAN F0.8 and F0.10). Each is
//! generated by the crate that owns the types, so it cannot be edited by hand and cannot drift from the code:
//!
//! | File | Content | Generated by |
//! | --- | --- | --- |
//! | `docs/openapi.json` | OpenAPI 3.1 document of `/api/v1`, with `x-required-scope` on every operation | `davhaven_api::document` |
//! | `docs/contracts/mcp-tools.json` | MCP tools with input and output schemas and annotations | `davhaven_wire::mcp::tools_document` |
//! | `docs/contracts/events.schema.json` | the webhook envelope and the payload of every event type | `davhaven_wire::schema::events_schema` |
//!
//! `cargo xtask contracts` writes the files; `cargo xtask contracts --check` (the `contracts` CI job) fails when a
//! committed file differs from what the code generates and names the first difference. The text is canonical:
//! object keys are sorted at every level, two-space indentation, a final newline, so the same code always yields the
//! same bytes whatever order a library iterates in.

use std::path::{Path, PathBuf};

use cargo_metadata::MetadataCommand;
use serde_json::Value;

use crate::{XtaskError, print_line};

/// One generated contract document.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Document {
    /// The path relative to the workspace root, with `/` separators.
    pub(crate) path: &'static str,
    /// The canonical JSON text.
    pub(crate) content: String,
}

/// The state of one document after a run.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum Status {
    /// The committed file equals the generated text.
    Current,
    /// The committed file is missing or differs; the text says where.
    Stale(String),
    /// The file was written (generate mode).
    Written,
}

/// `value` with the keys of every object sorted, so that serialization does not depend on iteration order.
pub(crate) fn canonical(value: &Value) -> Value {
    match value {
        Value::Object(members) => {
            let mut entries: Vec<(&String, &Value)> = members.iter().collect();
            entries.sort_by(|left, right| left.0.cmp(right.0));
            Value::Object(
                entries
                    .into_iter()
                    .map(|(key, member)| (key.clone(), canonical(member)))
                    .collect(),
            )
        }
        Value::Array(items) => Value::Array(items.iter().map(canonical).collect()),
        other => other.clone(),
    }
}

/// The canonical text of a document: sorted keys, two-space indentation, a final newline.
pub(crate) fn render(value: &Value) -> String {
    let mut text = serde_json::to_string_pretty(&canonical(value)).unwrap_or_else(|_| "null".to_owned());
    text.push('\n');
    text
}

/// Every contract document, generated from the code of this checkout.
pub(crate) fn documents() -> Result<Vec<Document>, XtaskError> {
    let openapi = serde_json::to_value(davhaven_api::document()).map_err(XtaskError::Serialize)?;
    Ok(vec![
        Document {
            path: "docs/openapi.json",
            content: render(&openapi),
        },
        Document {
            path: "docs/contracts/mcp-tools.json",
            content: render(&davhaven_wire::mcp::tools_document()),
        },
        Document {
            path: "docs/contracts/events.schema.json",
            content: render(&davhaven_wire::schema::events_schema()),
        },
    ])
}

/// A short description of the first line where `committed` and `generated` differ.
pub(crate) fn first_difference(committed: &str, generated: &str) -> String {
    let mut committed_lines = committed.lines();
    let mut generated_lines = generated.lines();
    let mut number = 1_usize;
    loop {
        match (committed_lines.next(), generated_lines.next()) {
            (Some(left), Some(right)) if left == right => number += 1,
            (Some(left), Some(right)) => {
                return format!("line {number}: committed `{}`, generated `{}`", clip(left), clip(right));
            }
            (Some(left), None) => return format!("line {number}: committed `{}`, generated nothing", clip(left)),
            (None, Some(right)) => return format!("line {number}: committed nothing, generated `{}`", clip(right)),
            (None, None) => return "the files differ only in line endings or the final newline".to_owned(),
        }
    }
}

/// The first 80 characters of a line, for messages.
fn clip(line: &str) -> String {
    let trimmed = line.trim();
    let mut clipped: String = trimmed.chars().take(80).collect();
    if trimmed.chars().count() > 80 {
        clipped.push('…');
    }
    clipped
}

/// Writes one document or compares it with the committed file.
pub(crate) fn sync_document(root: &Path, document: &Document, check: bool) -> Result<Status, XtaskError> {
    let path = root.join(document.path);
    if check {
        return Ok(match std::fs::read_to_string(&path) {
            Ok(committed) if committed == document.content => Status::Current,
            Ok(committed) => Status::Stale(first_difference(&committed, &document.content)),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                Status::Stale("the file does not exist".to_owned())
            }
            Err(source) => return Err(XtaskError::Read { path, source }),
        });
    }
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).map_err(|source| XtaskError::Write {
            path: parent.to_path_buf(),
            source,
        })?;
    }
    std::fs::write(&path, &document.content).map_err(|source| XtaskError::Write { path, source })?;
    Ok(Status::Written)
}

/// The root of the workspace this tool runs in.
fn workspace_root() -> Result<PathBuf, XtaskError> {
    let metadata = MetadataCommand::new().no_deps().exec()?;
    Ok(metadata.workspace_root.into_std_path_buf())
}

/// Generates the contract documents, or with `check` verifies that the committed files are current.
pub(crate) fn run(check: bool) -> Result<bool, XtaskError> {
    let root = workspace_root()?;
    let mut clean = true;
    for document in documents()? {
        match sync_document(&root, &document, check)? {
            Status::Current => print_line(format_args!("contracts: {} is up to date", document.path)),
            Status::Written => print_line(format_args!("contracts: wrote {}", document.path)),
            Status::Stale(difference) => {
                clean = false;
                print_line(format_args!(
                    "error: {} is out of date ({difference}); run `cargo xtask contracts` and commit the result",
                    document.path
                ));
            }
        }
    }
    Ok(clean)
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    #[test]
    fn keys_are_sorted_at_every_level_and_arrays_keep_their_order() {
        let value = json!({"b": {"y": 1, "x": [3, 1, 2]}, "a": [{"z": 0, "c": 1}]});
        let text = render(&value);
        assert_eq!(
            text,
            "{\n  \"a\": [\n    {\n      \"c\": 1,\n      \"z\": 0\n    }\n  ],\n  \"b\": {\n    \"x\": [\n      3,\n      1,\n      2\n    ],\n    \"y\": 1\n  }\n}\n"
        );
        assert_eq!(render(&value), render(&canonical(&value)), "rendering is idempotent");
    }

    #[test]
    fn the_documents_are_json_with_the_expected_roots() {
        let documents = documents().unwrap();
        let paths: Vec<&str> = documents.iter().map(|document| document.path).collect();
        assert_eq!(
            paths,
            vec![
                "docs/openapi.json",
                "docs/contracts/mcp-tools.json",
                "docs/contracts/events.schema.json"
            ]
        );
        for document in &documents {
            assert!(document.content.ends_with("}\n"), "{}", document.path);
            let parsed: Value = serde_json::from_str(&document.content).unwrap();
            assert_eq!(render(&parsed), document.content, "{} is canonical", document.path);
        }
        let openapi: Value = serde_json::from_str(&documents[0].content).unwrap();
        assert!(openapi["openapi"].as_str().unwrap().starts_with("3.1"));
        let paths: std::collections::BTreeSet<&str> =
            davhaven_api::openapi::ROUTES.iter().map(|route| route.path).collect();
        assert_eq!(openapi["paths"].as_object().unwrap().len(), paths.len());
        let tools: Value = serde_json::from_str(&documents[1].content).unwrap();
        assert_eq!(
            tools["tools"].as_array().unwrap().len(),
            davhaven_wire::mcp::TOOLS.len()
        );
        let events: Value = serde_json::from_str(&documents[2].content).unwrap();
        assert!(
            events["events"].as_array().unwrap().len() >= 20,
            "the plan lists 20 event types"
        );
    }

    #[test]
    fn generation_is_deterministic() {
        assert_eq!(documents().unwrap(), documents().unwrap());
    }

    #[test]
    fn differences_are_located() {
        assert_eq!(
            first_difference("a\nb\nc\n", "a\nX\nc\n"),
            "line 2: committed `b`, generated `X`"
        );
        assert_eq!(
            first_difference("a\n", "a\nb\n"),
            "line 2: committed nothing, generated `b`"
        );
        assert_eq!(
            first_difference("a\nb\n", "a\n"),
            "line 2: committed `b`, generated nothing"
        );
        assert!(first_difference("a\n", "a").contains("final newline"));
        // A checkout with CRLF line endings differs from the generated text without a differing line.
        assert_eq!(
            first_difference("a\r\nb\r\n", "a\nb\n"),
            "the files differ only in line endings or the final newline"
        );
        let long = "x".repeat(200);
        assert!(first_difference(&long, "y").contains('…'));
    }

    #[test]
    fn lines_are_clipped_after_eighty_characters_counted_as_characters() {
        assert_eq!(clip(&"x".repeat(80)), "x".repeat(80));
        assert_eq!(clip(&"x".repeat(81)), format!("{}…", "x".repeat(80)));
        // Multi-byte characters are never cut in the middle.
        assert_eq!(clip(&"é".repeat(81)), format!("{}…", "é".repeat(80)));
        assert_eq!(clip("   indented  "), "indented");
    }

    #[test]
    fn check_mode_reports_missing_stale_and_current_files() {
        let root = tempfile::tempdir().unwrap();
        let document = Document {
            path: "docs/contracts/sample.json",
            content: "{\n  \"a\": 1\n}\n".to_owned(),
        };
        let missing = sync_document(root.path(), &document, true).unwrap();
        assert_eq!(missing, Status::Stale("the file does not exist".to_owned()));
        assert!(
            !root.path().join("docs").exists(),
            "check mode creates neither the file nor its directory"
        );
        assert_eq!(sync_document(root.path(), &document, false).unwrap(), Status::Written);
        assert_eq!(sync_document(root.path(), &document, true).unwrap(), Status::Current);
        std::fs::write(root.path().join(document.path), "{\n  \"a\": 2\n}\n").unwrap();
        let stale = sync_document(root.path(), &document, true).unwrap();
        assert_eq!(
            stale,
            Status::Stale("line 2: committed `\"a\": 2`, generated `\"a\": 1`".to_owned())
        );
        assert_eq!(
            std::fs::read_to_string(root.path().join(document.path)).unwrap(),
            "{\n  \"a\": 2\n}\n",
            "check mode leaves a stale file as it is"
        );
        assert_eq!(sync_document(root.path(), &document, false).unwrap(), Status::Written);
        assert_eq!(sync_document(root.path(), &document, true).unwrap(), Status::Current);
    }
}
